(32511, 'Acts 2:3', 'Acts', 2, 3, 'هلته هغوی ته د اور د لمبو په شان ژبې راښکاره شوې او په هغوی هر یو باندې نازلې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_3.mp3', '', 1761754199, 1761754199),
(32512, 'Acts 2:4', 'Acts', 2, 4, 'هغوی ټول د روح القدس څخه ډک شول او څنګه چې روح القدس هغوی ته د خبرو کولو توان ورکړ، نو په نورو ژبو یې خبرې پیل کړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_4.mp3', '', 1761754199, 1761754199),
(32513, 'Acts 2:5', 'Acts', 2, 5, 'په هغه وخت کې پرهېزګاره یهودیان چې د نړۍ د هر هېواد څخه راغلي وو، په اورشلیم کې اوسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_5.mp3', '', 1761754199, 1761754199),
(32514, 'Acts 2:6', 'Acts', 2, 6, 'کله چې هغوی دا اواز واورېد، نو ډېر خلک سره راټول شول او حیران پاتې شول، ځکه چې هر یو د ایماندارانو خبرې په خپلو ژبو باندې اورېدلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_6.mp3', '', 1761754199, 1761754199),
(32515, 'Acts 2:7', 'Acts', 2, 7, 'هغوی ډېر حیران پاتې وو او ویل یې: «ایا دا ټول جلیلیان نه دي چې خبرې کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_7.mp3', '', 1761754199, 1761754199),
(32516, 'Acts 2:8', 'Acts', 2, 8, 'نو بیا څنګه مونږ هر یو په خپله مورنۍ ژبه د هغوی خبرې اورو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_8.mp3', '', 1761754199, 1761754199),
(32517, 'Acts 2:9', 'Acts', 2, 9, 'مونږ پارتیانو، مادیانو، ایلامیانو، د بین النهرین اوسېدونکو، د یهودیې او کپدوکیې، پونتوس، د اسیا د ولایت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_9.mp3', '', 1761754199, 1761754199),
(32518, 'Acts 2:10', 'Acts', 2, 10, 'او فریجیې او پمفیلیې، مصر او لیبیا د سیمو څخه چې د قیروان ښار ته نژدې دي، رومي مسافران', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_10.mp3', '', 1761754199, 1761754199),
(32519, 'Acts 2:11', 'Acts', 2, 11, 'چې اصلي یهودیان او څوک چې یهودیان شوي دي، کریتیان او عربان یو. خو بیاهم مونږ د هغوی خبرې چې د خدای د حیرانوونکو کارونو په هکله یې کوي په خپلو خپلو ژبو اورو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_11.mp3', '', 1761754199, 1761754199),
(32520, 'Acts 2:12', 'Acts', 2, 12, 'هغوی حیران او وارخطا ولاړ وو او یو د بله څخه یې پوښتنه کوله چې دا څه معنی لري؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_12.mp3', '', 1761754199, 1761754199),
(32521, 'Acts 2:13', 'Acts', 2, 13, 'خو نورو به ملنډې وهلې او ویل به یې چې دا خلک نشه دي. د پطروس وعظ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_13.mp3', '', 1761754199, 1761754199),
(32522, 'Acts 2:14', 'Acts', 2, 14, 'بیا پطروس د نورو یوولسو رسولانو سره ودرېده او په لوړ اواز یې د خلکو ګڼې‌ګوڼې ته په وینا کې وویل: «ای یهودیانو او د اورشلیم اوسېدونکو! زه چې څه وایم، غواړم په هغې باندې پوه شئ او په غور سره یې واورئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_14.mp3', '', 1761754199, 1761754199),
(32523, 'Acts 2:15', 'Acts', 2, 15, 'لکه څنګه چې تاسو فکر کوئ دا خلک نشه نه دي، ځکه چې اوس لا د سهار نهه بجې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_15.mp3', '', 1761754199, 1761754199),
(32524, 'Acts 2:16', 'Acts', 2, 16, 'بلکې دا هغه څه دي چې یوییل نبي د هغه په هکله ویلي وو:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_16.mp3', '', 1761754199, 1761754199),
(32525, 'Acts 2:17', 'Acts', 2, 17, 'خدای وایي: په اخرو ورځو کې به داسې وشي. زه به خپل روح کړمه نازل په ټولو خلکو باندې ستاسو لورګانې او زامن به زما پیغام رسوي ستاسو ځوانان به رویاګانې ویني او ستاسو سپین‌ږیري به خوبونه ویني', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_17.mp3', '', 1761754199, 1761754199),
(32526, 'Acts 2:18', 'Acts', 2, 18, 'هو، په هغو ورځو کې حتی په خپلو غلامانو او وینځو باندې به هم خپل روح نازل کړم او دوی به زما پیغام رسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_18.mp3', '', 1761754199, 1761754199),
(32527, 'Acts 2:19', 'Acts', 2, 19, 'زه به پاس په اسمان کې عجیبه کارونه وښایم او لاندې په ځمکه باندې حیرانوونکې نښې یعنې وینه، اور او سخت لوګی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_19.mp3', '', 1761754199, 1761754199),
(32528, 'Acts 2:20', 'Acts', 2, 20, 'مخکې له دې چې د څښتن ورځ راشي یعنې لویه او د جلال ورځ، نو لمر به په تیاره باندې بدل شي او د سپوږمۍ رنګ به لکه د وینې په شان سوري شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_20.mp3', '', 1761754199, 1761754199),
(32529, 'Acts 2:21', 'Acts', 2, 21, 'نو بیا به داسې وشي چې هرڅوک د څښتن په نوم چې مرسته وغواړي، هغه به وژغورل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_21.mp3', '', 1761754199, 1761754199),
(32530, 'Acts 2:22', 'Acts', 2, 22, 'ای د اسراییلو خلکو! دې خبرو ته غوږ ونیسئ: ناصري عیسی یو سړی ؤ چې خدای هغه تاسو ته د معجزو، حیرانوونکو کارونو او نښو له لارې چې خدای د هغه په وسیله ستاسو په منځ کې وښودلې، ثابته کړه چې هغه څوک دی، لکه څنګه چې تاسو په خپله ورباندې خبر یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_22.mp3', '', 1761754199, 1761754199),
(32531, 'Acts 2:23', 'Acts', 2, 23, 'دا سړی تاسو ته د خدای د ټینګې ارادې او پوهې له مخې په لاس درکړل شو او تاسو هغه د بدکارانو په مرسته په صلیب ځوړند او مړ مو کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_23.mp3', '', 1761754199, 1761754199),
(32532, 'Acts 2:24', 'Acts', 2, 24, 'خو خدای هغه بېرته راژوندی کړ او د مرګ د عذاب څخه یې خلاص کړ، ځکه چې مرګ نه شو کولای هغه په خپلو منګولو کې وساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_24.mp3', '', 1761754199, 1761754199),
(32533, 'Acts 2:25', 'Acts', 2, 25, 'ځکه چې داود د هغه په هکله ویلي وو: ‹زه وینم چې تل څښتن زما سره دی هغه موجود دی زما ښي لاس ته چې زه ونه غورځېږم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_25.mp3', '', 1761754199, 1761754199),
(32534, 'Acts 2:26', 'Acts', 2, 26, 'نو زما زړه دی خوشحال کله چې کړم خبرې نو ډېر خوشحاله یمه او اوسي په هیله کې به ارام بدن زما', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_26.mp3', '', 1761754199, 1761754199),
(32535, 'Acts 2:27', 'Acts', 2, 27, 'ځکه چې ته به ما پرېنږدې د مړو په دنیا کې او ته به پرېنږدې مړی د خپل سپېڅلي خادم چې شي خراب', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_27.mp3', '', 1761754199, 1761754199),
