(32537, 'Acts 2:29', 'Acts', 2, 29, 'ای ګرانو دوستانو! زه کولای شم په پوره ډاډ سره د خپل نیکه داود په هکله تاسو ته ووایم چې هغه مړ شو او ښخ شو او د هغه قبر تر نن ورځې پورې دلته موجود دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_29.mp3', '', 1761754199, 1761754199),
(32538, 'Acts 2:30', 'Acts', 2, 30, 'خو داود پیغمبر ؤ او پوهېده چې خدای ورسره وعده کړې او قسم یې خوړلی چې د هغه د اولادې څخه به یو کس د پاچاهۍ په تخت کښېنوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_30.mp3', '', 1761754199, 1761754199),
(32539, 'Acts 2:31', 'Acts', 2, 31, 'داود پوهېده چې څه به کیږي او ویلي یې وو چې مسیح به بیا راژوندی کیږي. هغه وویل چې خدای به هغه د مړو په دنیا کې پرېنږدي او نه به د هغه مړی خرابېدلو ته پرېږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_31.mp3', '', 1761754199, 1761754199),
(32540, 'Acts 2:32', 'Acts', 2, 32, 'خدای همدا عیسی د مړو څخه راژوندی کړ او مونږ ټول د دې شاهدان یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_32.mp3', '', 1761754199, 1761754199),
(32541, 'Acts 2:33', 'Acts', 2, 33, 'نو بیا عیسی پورته یووړل شو چې د خدای ښي لاس ته کښېني او هغه د اسماني پلار له خوا وعده شوی روح القدس تر‌لاسه کړ او په مونږ باندې یې نازل کړ چې اوس یې تاسو وینئ او اورئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_33.mp3', '', 1761754199, 1761754199),
(32542, 'Acts 2:34', 'Acts', 2, 34, 'ځکه چې داود خپله اسمان ته نه ؤ پورته شوی، خو هغه وایي: څښتن وویل زما بادار ته کښېنه زما ښي لاس ته', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_34.mp3', '', 1761754199, 1761754199),
(32543, 'Acts 2:35', 'Acts', 2, 35, 'ترڅو ستا دښمنان کړم ستا د پښو لاندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_35.mp3', '', 1761754199, 1761754199),
(32544, 'Acts 2:36', 'Acts', 2, 36, 'نو د اسراییلو ټول خلک دې په یقین سره په دې پوه شي چې هغه عیسی چې تاسو په صلیب ځوړند کړی ؤ، خدای هغه څښتن او مسیح وټاکه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_36.mp3', '', 1761754199, 1761754199),
(32545, 'Acts 2:37', 'Acts', 2, 37, 'کله چې خلکو دا واورېدل، نو زړونه یې مات شول. هغوی پطروس او نورو رسولانو ته وویل: «ای ګرانو دوستانو! مونږ باید څه وکړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_37.mp3', '', 1761754199, 1761754199),
(32546, 'Acts 2:38', 'Acts', 2, 38, 'پطروس هغوی ته وویل: «تاسو هر یو باید د خپلو ګناهونو نه توبه وباسئ او د عیسی مسیح په نوم د تعمید غسل واخلئ، په دې ډول به ستاسو ګناهونه وبخښل شي او روح القدس به د یو نعمت په توګه تر‌لاسه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_38.mp3', '', 1761754199, 1761754199),
(32547, 'Acts 2:39', 'Acts', 2, 39, 'ځکه چې دا وعده ستاسو سره، ستاسو د اولادونو او هغو خلکو سره ده چې په لېرې ځایونو کې اوسیږي، یعنې د هغو ټولو سره چې زمونږ څښتن خدای یې خپل ځان ته رابولي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_39.mp3', '', 1761754199, 1761754199),
(32548, 'Acts 2:40', 'Acts', 2, 40, 'پطروس هغوی ته نورې ډېرې خبرې وکړې او هغوی ته یې خبرداری ورکړ او ویې ویل: «خپل ځانونه د دې زمانې د بدکارو خلکو څخه وساتئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_40.mp3', '', 1761754199, 1761754199),
(32549, 'Acts 2:41', 'Acts', 2, 41, 'کومو خلکو چې د پطروس پیغام ومانه، نو هغوی ته د تعمید غسل ورکړل شو. په هغه ورځ شاوخوا درې زره کسان د ایماندارانو د ډلې سره یوځای شول. د ایماندارانو ژوند', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_41.mp3', '', 1761754199, 1761754199),
(32550, 'Acts 2:42', 'Acts', 2, 42, 'ایماندارانو خپل وخت د رسولانو څخه د تعلیم په اورېدلو، د یو بل سره په ملګرتیا، په ګډه سره د ډوډۍ په خوړلو او دعا کولو تېراوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_42.mp3', '', 1761754199, 1761754199),
(32551, 'Acts 2:43', 'Acts', 2, 43, 'د هغو حیرانوونکو کارونو او معجزو له امله چې د رسولانو په وسیله به ښودل کېدلې، د ټولو په زړونو کې به وېره پیدا کېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_43.mp3', '', 1761754199, 1761754199),
(32552, 'Acts 2:44', 'Acts', 2, 44, 'ټول ایمانداران به سره راټولېدل او هغوی چې هرڅه لرل نو ټول به په کې شریک وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_44.mp3', '', 1761754199, 1761754199),
(32553, 'Acts 2:45', 'Acts', 2, 45, 'هغوی به خپل مال او جایداد خرڅاوه او هر یو ته به یې د هغه د اړتیاوو له مخې پیسې ورکولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_45.mp3', '', 1761754199, 1761754199),
(32554, 'Acts 2:46', 'Acts', 2, 46, 'هغوی به هره ورځ د خدای په کور کې سره راټولېدل او په خپلو کورونو کې به یې په خوشحالۍ او اخلاص یوځای ډوډۍ خوړله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_46.mp3', '', 1761754199, 1761754199),
(32555, 'Acts 2:47', 'Acts', 2, 47, 'هغوی به د خدای ثنا ویله او ټول خلک ترې خوشحاله وو او هره ورځ به چې څومره خلکو خلاصون مونده، نو څښتن به د هغوی په ډله کې شاملول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts2_verse_47.mp3', '', 1761754199, 1761754199),
(32556, 'Galatians 2:1', 'Galatians', 2, 1, 'څوارلس کاله وروسته یوځل بیا د برناباس سره اورشلیم ته لاړم او تیتوس مې هم د ځان سره بوته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_1.mp3', '', 1761754199, 1761754199),
(32557, 'Galatians 2:2', 'Galatians', 2, 2, 'زه د خدای د الهام له مخې هلته لاړم. هلته ما د کلیسا د هغو کسانو سره چې مشران ګڼل کېدل یوازې ولیدل او د هغوی سره مې د هغه زېري پیغام شریک کړ چې غیریهودیانو ته به مې ورکاوه. ما غوښتل په دې ډاډه شم چې کوم کار چې مې مخکې کړی ؤ او یا یې اوس کوم، هغه ګټه نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_2.mp3', '', 1761754199, 1761754199),
(32558, 'Galatians 2:3', 'Galatians', 2, 3, 'خو سره له دې چې زما ملګری تیتوس یوناني هم ؤ، خو هغه یې مجبوره نه کړ چې سنت شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_3.mp3', '', 1761754199, 1761754199),
(32559, 'Galatians 2:4', 'Galatians', 2, 4, 'که څه هم ځینې خلکو چې خپل ځانونه یې ایمانداران ښودل، په پټه زمونږ په ډله کې راننوتلي وو چې جاسوسي وکړي، غوښتل چې دا کار وکړي او هغه ازادي چې مونږ په عیسی مسیح کې لرو، هغه له منځه یوسي. هغوی غوښتل چې مونږ غلامان کړي او دې ته مو مجبور کړي چې د هغوی د یهودیت د قوانینو پیروي وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_4.mp3', '', 1761754199, 1761754199),
(32560, 'Galatians 2:5', 'Galatians', 2, 5, 'خو مونږ یوه شېبه هم هغوی ته موقعه ورنه کړه چې د هغوی تعلیم ته غاړه کېږدو، ځکه چې مونږ غوښتل د زېري رښتینولي د تل دپاره په تاسو کې خوندي پاتې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_5.mp3', '', 1761754199, 1761754199),
(32561, 'Galatians 2:6', 'Galatians', 2, 6, 'او کوم خلک چې مشران ګڼل کېدل، زما په پیغام کې هېڅ شی زیات نه کړل. خو زما دپاره فرق نه کوي که هغوی هر څنګه وو، ځکه چې خدای د هېچا د ظاهري شکل په هکله قضاوت نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_6.mp3', '', 1761754199, 1761754199),
(32562, 'Galatians 2:7', 'Galatians', 2, 7, 'د دې په ځای، هغوی ولیدل چې خدای ماته دا وظیفه سپارلې ده چې ناسنت شویو غیریهودیانو ته زېری ورسوم، لکه څنګه چې پطروس ته د سنت شویو یهودیانو ته د زېري رسولو وظیفه سپارل شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_7.mp3', '', 1761754199, 1761754199),
(32563, 'Galatians 2:8', 'Galatians', 2, 8, 'ځکه هماغه خدای چې پطروس ته یې قدرت ورکړ چې د یهودیانو رسول اوسي، ماته یې هم قدرت راکړ چې د غیریهودیانو رسول واوسم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_8.mp3', '', 1761754199, 1761754199),
(32564, 'Galatians 2:9', 'Galatians', 2, 9, 'کله چې یعقوب، پطروس او یوحنا چې د کلیسا مشران ګڼل کېدل، د خدای هغه فضل ولیده چې ماته راکړل شوی ؤ، نو هغوی برناباس او ماته د ملګرتیا لاس راکړ. په دې سره جوړ راغلو چې مونږ به په غیریهودیانو کې او هغوی به د یهودیانو په منځ کې کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_9.mp3', '', 1761754199, 1761754199),
(32565, 'Galatians 2:10', 'Galatians', 2, 10, 'د هغوی یوازېنۍ غوښتنه دا وه چې باید د غریبانو په فکر کې واوسو، دا هغه څه وو چې ما په شوق سره غوښتل ویې کړم. پولوس د پطروس سره مخالفت کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_10.mp3', '', 1761754199, 1761754199),
(32566, 'Galatians 2:11', 'Galatians', 2, 11, 'خو کله چې پطروس انطاکیې ته راغی نو ما مخامخ د هغه مخالفت وکړ، ځکه کوم کار چې هغه کړی ؤ، غلط ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_11.mp3', '', 1761754199, 1761754199),
(32567, 'Galatians 2:12', 'Galatians', 2, 12, 'ځکه مخکې له دې چې ځینې کسان چې د یعقوب له خوا رالېږل شوي وو هلته راورسیږي، پطروس د غیریهودیانو ایماندارانو سره په یو دسترخوان باندې کښېناست، خو د هغوی په رسېدلو سره هغه نور د غیریهودیانو سره خوړل څښل پرېښودل. پطروس خپل ځان له هغوی څخه بېل کړ، ځکه هغه د هغو خلکو څخه وېرېده چې د غیریهودیانو سنتول یې غوښتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_12.mp3', '', 1761754199, 1761754199),
(32568, 'Galatians 2:13', 'Galatians', 2, 13, 'نور یهودي ایمانداران هم په دې ریاکارۍ کې د پطروس سره یوځای شول، تر دې پورې چې برناباس هم د هغوی د ریاکارۍ له امله بې‌لارې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_13.mp3', '', 1761754199, 1761754199),
(32569, 'Galatians 2:14', 'Galatians', 2, 14, 'کله چې ما ولیدل د هغوی چلند او چلند د زېري د حقیقت سره سم نه دی، نو د ټولو په مخکې مې پطروس ته وویل: «سره له دې چې ته یهودي یې خو د غیریهودیانو په شان ژوند تېروې، نه د یهودیانو په شان، نو بیا څنګه کولای شې چې غیریهودیان دې ته مجبور کړې چې د یهودیانو په شان ژوند وکړي؟» یهودیان او غیریهودیان د ایمان په وسیله خلاصون مومي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_14.mp3', '', 1761754199, 1761754199),
(32570, 'Galatians 2:15', 'Galatians', 2, 15, 'مونږ د اصل نه یهودیان یو، خو د ګناهکارو غیریهودیانو په شان نه یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_15.mp3', '', 1761754199, 1761754199),
(32571, 'Galatians 2:16', 'Galatians', 2, 16, 'خو مونږ پوهېږو چې هېڅوک د شریعت په حکمونو باندې په عمل کولو سره نه، بلکې په عیسی مسیح باندې په ایمان راوړلو سره نېک ګڼل کیږي. مونږ په خپله هم په عیسی مسیح باندې ایمان راوړ، ترڅو په مسیح باندې په ایمان راوړلو سره نېک وګڼل شو، نه د شریعت په سرته رسولو سره. ځکه چې هېڅوک نه شي کولای د شریعت په حکمونو باندې په عمل کولو سره نېک وګڼل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_16.mp3', '', 1761754199, 1761754199),
(32572, 'Galatians 2:17', 'Galatians', 2, 17, 'که چېرې مونږ هڅه کوو چې په مسیح باندې د ایمان راوړلو په وسیله نېک وګڼل شو، خو په دې ګناهکاران ګڼل کېږو چې شریعت مو پریښی دی، نو ایا د دې معنی دا شوه چې مسیح زمونږ د ګناه سبب شو؟ هېڅکله نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_17.mp3', '', 1761754199, 1761754199),
(32573, 'Galatians 2:18', 'Galatians', 2, 18, 'که چېرې زه هغه شریعت بیا جوړوم چې په خپله مې خراب کړی دی، نو زه به خپل ځان د شریعت ماتوونکی وښایم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_18.mp3', '', 1761754199, 1761754199),
(32574, 'Galatians 2:19', 'Galatians', 2, 19, 'ځکه کله چې ما په شریعت باندې د عمل کولو کوښښ کاوه، زه یې محکوم کړم، نو د شریعت له مخې مړ شوم. نو ما د هغه د ټولو شرایطو پوره کول پرېښودل، ترڅو د خدای د ارادې سره سم ژوند وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_19.mp3', '', 1761754199, 1761754199),
(32575, 'Galatians 2:20', 'Galatians', 2, 20, 'زه د مسیح سره په صلیب شوم، نو زه نور ژوندی نه یم، بلکې مسیح په ما کې اوسیږي. اوس چې زه کوم ژوند تېروم، هغه د خدای په زوی باندې د ایمان لرلو په وسیله دی چې زما سره یې مینه وکړه او خپل ژوند یې زما دپاره له لاسه ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_20.mp3', '', 1761754199, 1761754199),
(32576, 'Galatians 2:21', 'Galatians', 2, 21, 'زه د خدای فضل بې‌ګټې نه ګڼم، ځکه که چېرې عدالت په شریعت باندې د عمل کولو له لارې حاصلېدلای شوای، نو بیا اړتیا نه وه چې مسیح دې مړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians2_verse_21.mp3', '', 1761754199, 1761754199),
(32577, 'Titus 1:1', 'Titus', 1, 1, 'دا لیک د پولوس له خوا چې د خدای خدمتګار او د عیسی مسیح رسول دی، لیکل شوی دی. زه د دې دپاره ټاکل شوی یم چې د خدای د غوره شویو خلکو ایمان قوي کړم او هغوی ته تعلیم ورکړم، ترڅو په هغه حقیقت پوه شي چې هغوی ته دا ورزده کوي چې څنګه د دیندارۍ ژوند وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_1.mp3', '', 1761754199, 1761754199),
(32578, 'Titus 1:2', 'Titus', 1, 2, 'دا هغه حقیقت دی چې هغوی ته د تلپاتې ژوندون هیله ورکوي. خدای چې هېڅکله دروغ نه وایي، د ازل نه دا وعده کړې ده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_2.mp3', '', 1761754199, 1761754199),
(32579, 'Titus 1:3', 'Titus', 1, 3, 'او هغه دا په ټاکلی وخت کې په خپل کلام کې ښکاره کړ. دا کار ماته وسپارل شو چې زه د هغه په اړه د خپل خلاصوونکي خدای د حکم اعلان وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_3.mp3', '', 1761754199, 1761754199),
(32580, 'Titus 1:4', 'Titus', 1, 4, 'زه دا لیک تیتوس ته لیکم چې زما رښتینی زوی دی او په ایمان کې سره شریک یو. د پلار خدای او زمونږ د خلاصوونکي عیسی مسیح فضل او سلامتي دې وي په تا باندې. په کلیسا کې د مشرانو ټاکل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_4.mp3', '', 1761754199, 1761754199),
(32581, 'Titus 1:5', 'Titus', 1, 5, 'ته مې د دې دپاره په کریت کې پرېښودلې، ترڅو پاتې کارونه تنظیم کړې او لکه څنګه چې مې درته لارښوونه کړې ده چې په هر ښار کې د کلیساګانو دپاره مشران وټاکې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_5.mp3', '', 1761754199, 1761754199),
(32582, 'Titus 1:6', 'Titus', 1, 6, 'مشران باید بې‌عیبه وي، یوازې یوه ښځه ولري، اولادونه یې ایمانداران وي او په هغوی باندې دې د بد‌اخلاقۍ او سرکښۍ تورونه نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_6.mp3', '', 1761754199, 1761754199),
(32583, 'Titus 1:7', 'Titus', 1, 7, 'څرنګه چې د کلیسا مشر د خدای د کور مسوول دی، نو هغه باید بې‌عیبه وي. هغه باید مغرور نه وي، تندخویه، شرابي، جګړه‌مار او د پیسو حرص ورسره نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_7.mp3', '', 1761754199, 1761754199),
(32584, 'Titus 1:8', 'Titus', 1, 8, 'هغه باید مېلمه‌پال او خیرخواه وي، په خپل نفس باندې واک ولري، عادل، سپېڅلی، سم او منظم وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_8.mp3', '', 1761754199, 1761754199),
(32585, 'Titus 1:9', 'Titus', 1, 9, 'هغه باید په هغه باوري پیغام باندې چې ورته تعلیم ورکړل شوی دی ټینګ ودریږي، ترڅو په خپل رښتیني تعلیم سره وکولای شي نور خلک وهڅوي او څوک چې ورسره مخالفت کوي هغوی دې په کلکه وغندي. بې‌لارې کوونکي ښوونکي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_9.mp3', '', 1761754199, 1761754199),
(32586, 'Titus 1:10', 'Titus', 1, 10, 'ځکه چې ډېر داسې خلک شته چې سرکښي کوي، هغوی بېځایه خبرې کوي او خلک غولوي، په ځانګړې توګه هغه خلک چې په سنتولو باندې ټینګار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_10.mp3', '', 1761754199, 1761754199),
(32587, 'Titus 1:11', 'Titus', 1, 11, 'د داسې خلکو خولې باید وتړل شي، ځکه چې دوی د شرموونکې ګټې د لاسته راوړلو دپاره د هغو شیانو د تعلیم په وسیله چې باید ورنه کړل شي، د کورنیو ټول غړي تباه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_11.mp3', '', 1761754199, 1761754199),
(32588, 'Titus 1:12', 'Titus', 1, 12, 'د کریتیانو د عالمانو څخه یو عالم وایي: «کریتیان تل دروغجن، وحشیان، خېټور او تنبلان دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_12.mp3', '', 1761754199, 1761754199),
(32589, 'Titus 1:13', 'Titus', 1, 13, 'دا شاهدي رښتیا ده، نو هغوی سخت ورټه ترڅو په ایمان کې روغ پاتې شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_13.mp3', '', 1761754199, 1761754199),
(32590, 'Titus 1:14', 'Titus', 1, 14, 'او هغوی باید د یهودیانو زړو کیسو او د هغو خلکو حکمونو ته غوږ ونه نیسي چې حقیقت یې رد کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_14.mp3', '', 1761754199, 1761754199),
(32591, 'Titus 1:15', 'Titus', 1, 15, 'د پاکو خلکو دپاره ټول شیان پاک دي، خو د ناپاکو او بې‌ایمانه خلکو دپاره هېڅ شی پاک نه دی، ځکه چې د هغوی فکرونه او وجدانونه دواړه ناپاکه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_15.mp3', '', 1761754199, 1761754199),
(32592, 'Titus 1:16', 'Titus', 1, 16, 'هغوی دعوه کوي چې مونږ خدای پېژنو، خو په عمل کې هغوی د هغه نه انکار کوي. هغوی د کرکې وړ او نافرمانه دي او د هېڅ نېک کار کولو وړتیا نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus1_verse_16.mp3', '', 1761754199, 1761754199),
(32593, 'Revelation 18:1', 'Revelation', 18, 1, 'له دې نه وروسته ما یوه بله فرښته ولیدله چې د اسمان څخه راښکته کېدله. هغې ډېر واک او اختیار درلود او ځمکه د هغې د شان او شوکت نه رڼا شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_1.mp3', '', 1761754199, 1761754199),
(32594, 'Revelation 18:2', 'Revelation', 18, 2, 'هغې په لوړ اواز سره نارې ووهلې: راولوېد، لوی بابل راولوېد! هغه شو د شیطانانو کور پناه ځای شو د پېریانو د هر ډول ناپاکو مرغانو پناه ځای شو او د ناپاکو او چټلو ځناورو پناه ځای شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_2.mp3', '', 1761754199, 1761754199),
(32595, 'Revelation 18:3', 'Revelation', 18, 3, 'ځکه چې څښلي دي ټولو قومونو د هغې د زناکارۍ او شهوت شراب پاچاهانو د دنیا کړې هغې سره زنا او شتمن شوي د نړۍ سوداګران په سبب د هغې د زیاتې عیاشۍ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_3.mp3', '', 1761754199, 1761754199),
(32596, 'Revelation 18:4', 'Revelation', 18, 4, 'بیا ما د اسمان نه یو بل اواز واورېد چې ویل یې: ای زما خلکو تاسو راووځئ د بابل د ښار څخه هسې نه چې شئ شریک د هغه په ګناهونو کې او راشي بلاګانې یې په تاسو باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_4.mp3', '', 1761754199, 1761754199),
(32597, 'Revelation 18:5', 'Revelation', 18, 5, 'ځکه د هغې د ګناهونو څخه دي جوړې شوې داسې لوړې ډېرۍ چې تر اسمانه رسي او خدای ته په یاد دي د هغې بد عملونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_5.mp3', '', 1761754199, 1761754199),
(32598, 'Revelation 18:6', 'Revelation', 18, 6, 'داسې چلند وکړئ هغې سره لکه چې څنګه هغې کړی دی د نورو سره کوم څه چې کړي دي هغې ورسره ویې کړئ دوه چنده تاسو کوم شراب چې تیار کړي دي هغې تاسو ته د دوه چنده قوي شرابو ورته ډکه کړئ پیاله د هغې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_6.mp3', '', 1761754199, 1761754199),
(32599, 'Revelation 18:7', 'Revelation', 18, 7, 'څومره لویي چې ورکوله خپل ځان ته هغې او عیاشي یې کوله هغومره ورکړئ ورته غم او عذاب ځکه چې خپل زړه کې هغه وایي: «زه یمه ناسته په تخت د ملکې په شان زه کونډه نه یم او وبه نه وینمه هېڅکله غم»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_7.mp3', '', 1761754199, 1761754199),
(32600, 'Revelation 18:8', 'Revelation', 18, 8, 'له دې امله په هغې باندې به راشي په یوه ورځ مصیبتونه داسې لکه مرګ، غم او قحطي او هغه به وسوځول شي په اور کې ځکه څښتن خدای چې قضاوت کړي د هغې په هکله هغه دی د قدرت خاوند', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_8.mp3', '', 1761754199, 1761754199),
(32601, 'Revelation 18:9', 'Revelation', 18, 9, 'د ځمکې هغو پاچاهانو چې د هغې سره زنا کړې ده او د هغې سره یې د عیاشۍ نه خوند اخیستی دی، کله چې د هغې د سوځېدلو لوګی وویني، نو د هغې په حال به وژاړي او ویر به وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_9.mp3', '', 1761754199, 1761754199),
(32602, 'Revelation 18:10', 'Revelation', 18, 10, 'هغوی به لېرې ولاړ وي او د هغې عذاب نه چې هغه به یې تېروي، ووېریږي او وبه وایي: افسوس، افسوس، ای د بابل لوی ښاره! ای قدرتمند ښاره! په یو ساعت کې سزا درکړل شوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_10.mp3', '', 1761754199, 1761754199),
(32603, 'Revelation 18:11', 'Revelation', 18, 11, 'د نړۍ سوداګران به هم په بابل باندې ژړا او ویر کوي، ځکه چې نور به هېڅوک هم د هغوی نه سودا نه اخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_11.mp3', '', 1761754199, 1761754199),
(32604, 'Revelation 18:12', 'Revelation', 18, 12, 'هېڅوک به د هغوی سره زر، سپین زر، قیمتي تیږې، مرغلرې، ښه کتان، بانجاني ټوټې، ورېښم، سرې ټوټې، ډول ډول خوشبویه لرګي، د فیل د غاښونو، قیمتي لرګیو، برنجو، اوسپنو او مرمرو نه جوړ شوي شیان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_12.mp3', '', 1761754199, 1761754199),
(32605, 'Revelation 18:13', 'Revelation', 18, 13, 'او ورسره دالچیني، مسالې، عطر، د مر کنډ، قیمتي خوشبویي، شراب، د زیتونو تېل، اوړه، غنم، غویان او پسونه وانخلي او په اسونو، ګاډۍ‌ګانو او په غلامانو او جنګي اسیرانو باندې یې سوداګري ونه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_13.mp3', '', 1761754199, 1761754199),
(32606, 'Revelation 18:14', 'Revelation', 18, 14, 'سوداګران به هغې ته ووایي: «هغه شیان چې تا یې ارمان کاوه چې خپل یې کړې، هغه دې ورکړل له لاسه، تا ورکړې ده له لاسه خپله ښکلا او شان او شوکت او نور به هېڅکله په لاس درنه شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_14.mp3', '', 1761754199, 1761754199),
(32607, 'Revelation 18:15', 'Revelation', 18, 15, 'هغه سوداګران به چې د هغې د شیانو د خرڅولو نه شتمن شوي وو، لېرې ولاړ وي او د هغې د عذاب نه چې هغه یې تېروي، ووېریږي او ویر او ژړا به کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_15.mp3', '', 1761754199, 1761754199),
(32608, 'Revelation 18:16', 'Revelation', 18, 16, 'او وایي به: افسوس، افسوس په دې لوی ښار چې به یې اغوستي وو ښه کتان، بانجاني او سره کالي او ښایسته شوی ؤ په سرو زرو، قیمتي تیږو او مرغلرو باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_16.mp3', '', 1761754199, 1761754199),
(32609, 'Revelation 18:17', 'Revelation', 18, 17, 'ځکه چې هغې په یو ساعت کې هغه ټوله شتمني له لاسه ورکړه. د کشتۍ ټول خاوندان، مسافران، کشتیوانان او هغه خلک چې د بحر له لارې به یې خپل کاروبار کاوه، لېرې ولاړ وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_17.mp3', '', 1761754199, 1761754199),
(32610, 'Revelation 18:18', 'Revelation', 18, 18, 'کله چې هغو د هغه ښار د سوځېدلو لوګی ولیده نو نارې یې ووهلې او ویې ویل: «د دې لوی ښار په شان به بل ښار چېرته وي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation18_verse_18.mp3', '', 1761754199, 1761754199);